  for (const c of s) {
    if (c === '(' || c === '[' || c === '{') {
      ngan.push(c)
    } else {
      // Đóng mà ngăn xếp rỗng, hoặc cái trên cùng không phải bạn của nó ⇒ hỏng ngay.
      if (ngan.pop() !== CAP[c]) return false
    }
  }
